<?php
require_once __DIR__.'/includes/functions.php';
$q=trim((string)($_GET['q']??''));$brand=trim((string)($_GET['brand']??''));$body=trim((string)($_GET['body']??''));$fuel=trim((string)($_GET['fuel']??''));$trans=trim((string)($_GET['transmission']??''));$max=(int)($_GET['max_price']??0);
$sql='SELECT * FROM cars WHERE is_active=1';$p=[];
if($q!==''){$sql.=' AND (name LIKE ? OR brand LIKE ? OR body_type LIKE ?)';$p[]="%$q%";$p[]="%$q%";$p[]="%$q%";}
if($brand!==''){$sql.=' AND brand=?';$p[]=$brand;}if($body!==''){$sql.=' AND body_type=?';$p[]=$body;}if($fuel!==''){$sql.=' AND fuel LIKE ?';$p[]="%$fuel%";}if($trans!==''){$sql.=' AND transmission LIKE ?';$p[]="%$trans%";}if($max>0){$sql.=' AND price_min<=?';$p[]=$max;}
$sql.=' ORDER BY featured DESC,price_min ASC';$st=$pdo->prepare($sql);$st->execute($p);$cars=$st->fetchAll();
$brands=$pdo->query('SELECT DISTINCT brand FROM cars WHERE is_active=1 ORDER BY brand')->fetchAll(PDO::FETCH_COLUMN);
$pageTitle='Explore cars';require __DIR__.'/includes/header.php';
?>
<div class="page-intro"><span class="eyebrow">THE CAR DIRECTORY</span><h1>Explore cars</h1><p class="muted">Search, filter and find the right fit for your next drive.</p></div>
<form class="filter-panel" method="get"><input name="q" value="<?= e($q) ?>" placeholder="Search car, brand or body type"><select name="brand"><option value="">All brands</option><?php foreach($brands as $b): ?><option <?= $brand===$b?'selected':'' ?>><?= e($b) ?></option><?php endforeach; ?></select><select name="body"><option value="">All body types</option><?php foreach(['SUV','Sedan','Hatchback','MPV','Coupe','Luxury SUV'] as $v): ?><option <?= $body===$v?'selected':'' ?>><?= e($v) ?></option><?php endforeach; ?></select><select name="fuel"><option value="">All fuel types</option><?php foreach(['Petrol','Diesel','Electric','Hybrid','CNG'] as $v): ?><option <?= $fuel===$v?'selected':'' ?>><?= e($v) ?></option><?php endforeach; ?></select><select name="transmission"><option value="">Any transmission</option><option <?= $trans==='Manual'?'selected':'' ?>>Manual</option><option <?= $trans==='Automatic'?'selected':'' ?>>Automatic</option></select><select name="max_price"><option value="">Any budget</option><?php foreach([500000,800000,1000000,1500000,2000000,3000000,5000000] as $v): ?><option value="<?= $v ?>" <?= $max===$v?'selected':'' ?>>Up to <?= money($v) ?></option><?php endforeach; ?></select><button class="btn">Apply filters</button><a class="btn btn-outline" href="<?= url('cars.php') ?>">Reset</a></form>
<div class="results-line"><b><?= count($cars) ?> cars found</b><span class="muted">Prices are indicative ex-showroom estimates.</span></div>
<div class="car-grid"><?php foreach($cars as $c): ?><article class="car-card"><a href="<?= url('car.php?id='.$c['id']) ?>" class="car-photo"><img src="<?= e(car_image($c['image_url'])) ?>" alt="<?= e($c['name']) ?>"><span class="photo-tag"><?= e($c['body_type']) ?></span></a><div class="car-info"><div class="muted tiny"><?= e($c['brand']) ?></div><h3><a href="<?= url('car.php?id='.$c['id']) ?>"><?= e($c['name']) ?></a></h3><div class="price"><?= money($c['price_min']) ?> – <?= money($c['price_max']) ?></div><div class="car-meta"><span><?= e($c['fuel']) ?></span><span><?= e($c['transmission']) ?></span><span><?= e($c['mileage']) ?></span></div><div class="card-actions"><a class="link" href="<?= url('car.php?id='.$c['id']) ?>">Details →</a><button class="compare-add" data-compare="<?= (int)$c['id'] ?>">+ Compare</button></div></div></article><?php endforeach; ?></div>
<?php if(!$cars): ?><div class="empty-state">No cars match those filters. Try a wider budget or reset filters.</div><?php endif; ?>
<?php require __DIR__.'/includes/footer.php'; ?>
